import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_lib_handl","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_lib_handl/index.md","filePath":"api/host/handl_plugin_lib_handl/index.md"}`),a={name:`api/host/handl_plugin_lib_handl/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-lib-handl" tabindex="-1">handl_plugin_lib_handl <a class="header-anchor" href="#handl-plugin-lib-handl" aria-label="Permalink to “handl_plugin_lib_handl”">​</a></h1><h1 id="handl-lib-handl-generic-hnl-library-loader" tabindex="-1">handl-lib-handl (generic <code>.hnl</code> library loader) <a class="header-anchor" href="#handl-lib-handl-generic-hnl-library-loader" aria-label="Permalink to “handl-lib-handl (generic .hnl library loader)”">​</a></h1><p>A generic crate that lets <code>.hnl</code> files replace hand-rolled Rust <code>plugin-lib-*</code> bridge crates for pure-logic libraries.</p><p>Each former pure-logic library crate (e.g. <code>plugin-lib-stats</code>, <code>plugin-lib-hello</code> — both now <code>plugin-lib-stdlib</code> package-table rows) had ~100+ lines of Rust bridge code that <code>include_str!</code>s a <code>.hnl</code> file, builds a cached per-thread <code>Runtime</code>, and evaluates a small applied expression per call. This crate eliminates that boilerplate with two reusable types:</p><ul><li><strong>[<code>HandlModule</code>]</strong> — implements <a href="./handl_platform::Module.html"><code>Module</code></a>, exposing every field of a <code>.hnl</code> record as a callable <a href="./handl_platform::Function.html"><code>Function</code></a>. Each call evaluates <code>(source).field(args)</code> via a cached per-thread <code>Runtime</code>.</li><li><strong>[<code>HandlLibraryPlugin</code>]</strong> — implements <a href="./handl_platform::Plugin.html"><code>Plugin</code></a>, contributing a [<code>HandlModule</code>] into the platform&#39;s [<code>ModuleRuntime</code>] during <code>contribute()</code>.</li></ul><h2 id="key-constraint-thread-local-ast" tabindex="-1">Key constraint (thread-local AST) <a class="header-anchor" href="#key-constraint-thread-local-ast" aria-label="Permalink to “Key constraint (thread-local AST)”">​</a></h2><p>The tree-walk engine indexes into a thread-local <code>CURRENT_AST</code> arena, so a handl closure <code>Value</code> produced by one bridge runtime cannot be cached and called later from an outer runtime. Therefore the <code>Runtime</code> is cached per-thread (via [<code>thread_local!</code>]), and the applied expression <code>(source).func(__arg_N)</code> — whose text is argument-independent (arguments cross the boundary as values bound directly on the call frame) — is lexed/parsed <strong>once</strong> per (module, function, arity) into a per-thread <code>AST_CACHE</code> <code>Rc&lt;Ast&gt;</code> and re-evaluated per call through [<code>Runtime::eval_shared_with_call_args</code>], which binds args directly into the <code>ScopeStack</code> globals map without cloning the engine. Caching the <em>evaluated</em> record is not possible across the <code>serde_json::Value</code> boundary: arrows capture earlier <code>do</code>-block bindings, and materializing each arrow&#39;s <code>env</code> expands recursively (exponential on ~100-binding modules like <code>str-handl</code>).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to “Usage”">​</a></h2><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_plugin_lib_handl::{HandlModule, HandlLibraryPlugin};</span></span>
<span class="line"><span>use handl_plugin_lib_stdlib as stdlib;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const STATS_HNL: &amp;str = include_str!(&quot;../../../handl-packages/stats/stats.hnl&quot;);</span></span>
<span class="line"><span>const STATS_FUNCS: &amp;[&amp;str] = &amp;[&quot;sum&quot;, &quot;avg&quot;, &quot;product&quot;, &quot;min&quot;, &quot;max&quot;, &quot;median&quot;, &quot;stddev&quot;];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let module = HandlModule::new(&quot;stats&quot;, STATS_HNL, STATS_FUNCS)</span></span>
<span class="line"><span>    .with_dependency(MathModule)</span></span>
<span class="line"><span>    .with_dependency(TypeModule);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Or as a plugin:</span></span>
<span class="line"><span>let plugin = HandlLibraryPlugin::new(&quot;stats&quot;, &quot;lib.stats&quot;, &quot;lib-stats&quot;, STATS_HNL, STATS_FUNCS);</span></span>
<span class="line"><span>// or via the package table: stdlib::library(&quot;stats&quot;)</span></span></code></pre></div><h2 id="text-transforms-adr-0094" tabindex="-1">Text transforms (ADR-0094) <a class="header-anchor" href="#text-transforms-adr-0094" aria-label="Permalink to “Text transforms (ADR-0094)”">​</a></h2><p>The text-level transform logic (<code>strip_declaration_lines</code>, <code>parse_*</code>, <code>expand_tag_declarations</code>, export→object rewriting, etc.) is canonically implemented in <code>handl-packages/loader/loader.hnl</code> — fully, in pure handl over the <code>char</code>/<code>str</code> floors. This crate keeps a two-level seam:</p><ul><li><code>mod bootstrap</code> — the irreducible Rust implementations. They prepare the <code>str</code> floor itself (<code>str-handl</code> needs <code>from &quot;char&quot; import</code> stripping before any loader exists — the bootstrap paradox) and are the correctness fallback: [<code>HandlLoader</code>] runs its module on the <strong>bytecode</strong> eval engine (<code>HandlModule::with_eval_engine</code>), which removed the interpreted <code>str.*</code>/<code>char.*</code> per-character cost that made the loader prohibitive under tree-walk (~59s → ~0.16s for <code>strip_decls</code> on the 22k-char <code>str-handl</code> source; see <code>examples/loader_bench.rs</code>).</li><li>[<code>HandlLoader</code>] / [<code>install_loader</code>] — the opt-in self-hosting seam. Once a host installs a loader built over <code>char</code> + <code>str</code> modules, every public transform here (and [<code>HandlModule::new</code>]&#39;s <code>analyze_source</code> pipeline) delegates to <code>loader.hnl</code>, falling back to <code>bootstrap</code> on any loader error.</li></ul><p><code>HandlModule::new_raw</code> loads the <code>loader</code> itself raw, without applying those transforms to its own source.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-lib-handl-1" tabindex="-1"><a href="./handl_plugin_lib_handl.html"><code>handl_plugin_lib_handl</code></a> <a class="header-anchor" href="#handl-plugin-lib-handl-1" aria-label="Permalink to “handl_plugin_lib_handl”">​</a></h3><p><em>1 trait, 10 structs, 11 constants, 2 type aliases, 34 functions, 4 statics, 5 modules</em></p><h3 id="handlfunction" tabindex="-1"><a href="./HandlFunction.html"><code>HandlFunction</code></a> <a class="header-anchor" href="#handlfunction" aria-label="Permalink to “HandlFunction”">​</a></h3><p><em>1 function</em></p><h3 id="handllibraryplugin" tabindex="-1"><a href="./HandlLibraryPlugin.html"><code>HandlLibraryPlugin</code></a> <a class="header-anchor" href="#handllibraryplugin" aria-label="Permalink to “HandlLibraryPlugin”">​</a></h3><p><em>2 functions</em></p><h3 id="handlloader" tabindex="-1"><a href="./HandlLoader.html"><code>HandlLoader</code></a> <a class="header-anchor" href="#handlloader" aria-label="Permalink to “HandlLoader”">​</a></h3><p><em>1 function</em></p><h3 id="handlmodule" tabindex="-1"><a href="./HandlModule.html"><code>HandlModule</code></a> <a class="header-anchor" href="#handlmodule" aria-label="Permalink to “HandlModule”">​</a></h3><p><em>10 functions</em></p><h3 id="moduleenv" tabindex="-1"><a href="./ModuleEnv.html"><code>ModuleEnv</code></a> <a class="header-anchor" href="#moduleenv" aria-label="Permalink to “ModuleEnv”">​</a></h3><p><em>6 functions</em></p><h3 id="bootstrap" tabindex="-1"><a href="./bootstrap.html"><code>bootstrap</code></a> <a class="header-anchor" href="#bootstrap" aria-label="Permalink to “bootstrap”">​</a></h3><p><em>24 functions</em></p><h3 id="model" tabindex="-1"><a href="./model.html"><code>model</code></a> <a class="header-anchor" href="#model" aria-label="Permalink to “model”">​</a></h3><p><em>1 function, 3 structs</em></p><h3 id="op-registry" tabindex="-1"><a href="./op_registry.html"><code>op_registry</code></a> <a class="header-anchor" href="#op-registry" aria-label="Permalink to “op_registry”">​</a></h3><p><em>1 trait, 2 structs</em></p><h3 id="op-registry-opfunction" tabindex="-1"><a href="./op_registry/OpFunction.html"><code>op_registry::OpFunction</code></a> <a class="header-anchor" href="#op-registry-opfunction" aria-label="Permalink to “op_registry::OpFunction”">​</a></h3><p><em>1 function</em></p><h3 id="op-registry-opregistry" tabindex="-1"><a href="./op_registry/OpRegistry.html"><code>op_registry::OpRegistry</code></a> <a class="header-anchor" href="#op-registry-opregistry" aria-label="Permalink to “op_registry::OpRegistry”">​</a></h3><p><em>2 functions</em></p><h3 id="op-registry-runtimepredicatechecker" tabindex="-1"><a href="./op_registry/RuntimePredicateChecker.html"><code>op_registry::RuntimePredicateChecker</code></a> <a class="header-anchor" href="#op-registry-runtimepredicatechecker" aria-label="Permalink to “op_registry::RuntimePredicateChecker”">​</a></h3><p><em>2 functions</em></p><h3 id="pkg" tabindex="-1"><a href="./pkg.html"><code>pkg</code></a> <a class="header-anchor" href="#pkg" aria-label="Permalink to “pkg”">​</a></h3><p><em>2 structs, 6 functions</em></p><h3 id="transform" tabindex="-1"><a href="./transform.html"><code>transform</code></a> <a class="header-anchor" href="#transform" aria-label="Permalink to “transform”">​</a></h3><p><em>1 struct, 8 constants, 8 functions</em></p>`,42)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};